def first_unique_char(s: str) -> int:
    char_count = OrderedDict()

    # Count occurrences of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the first unique character
    for index, (char, count) in enumerate(char_count.items()):
        if count == 1:
            return index

    return -1

