def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    dp = [[float('inf')] * cols for _ in range(rows)]

    def slide(x, y):
        if x < 0 or x >= rows or y < 0 or y >= cols:
            return float('inf')
        if dp[x][y] != float('inf'):
            return dp[x][y]

        dp[x][y] = 1 + min(slide(x-1, y), slide(x+1, y), slide(x, y-1), slide(x, y+1))
        return dp[x][y]

    result = float('inf')
    for i in range(rows):
        for j in range(cols):
            result = min(result, slide(i, j))

    return result - 1 if result != float('inf') else 0
