def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"
    digits = []
    while n != 0:
        remainder = n % 3
        if remainder == -1:
            digits.append('T')
            n = (n // 3) - 1
        elif remainder == 0:
            digits.append('0')
            n //= 3
        else:
            digits.append('1')
            n //= 3
    return ''.join(digits[::-1])
