import operator

def evaluate_expression(expr: str) -> int:
    ops = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv
    }

    tokens = expr.split()
    stack = []

    for token in tokens:
        if token.isdigit():
            stack.append(int(token))
        elif token in ops:
            b = stack.pop()
            a = stack.pop()
            result = ops[token](a, b)
            stack.append(result)

    return stack[0]

