import ast

def evaluate_expression(expression: str) -> float:
    try:
        # Parse the expression into an AST (Abstract Syntax Tree)
        parsed = ast.parse(expression, mode='eval')

        # Evaluate the AST safely using eval()
        result = eval(compile(parsed, filename="<ast>", mode="eval"))

        return result
    except Exception as e:
        raise ValueError(f"Invalid expression: {e}")

import operator

def evaluate_expression(expression: str) -> float:
    ops = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv
    }

    tokens = expression.split()
    stack = []

    for token in tokens:
        if token.isdigit():
            stack.append(float(token))
        elif token in ops:
            b = stack.pop()
            a = stack.pop()
            result = ops[token](a, b)
            stack.append(result)

    return stack[0]

