def shortest_path_one_break(grid: List[List[int]]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def bfs_with_break(start):
        queue = [(start, 0, False)]
        visited = set()

        while queue:
            (x, y), steps, broke = queue.pop(0)

            if (x, y) in visited:
                continue
            visited.add((x, y))

            if x == rows - 1 and y == cols - 1:
                return steps

