                if 0 <= nx < rows and 0 <= ny < cols:
                    if grid[nx][ny] == 1 and not broke:
                        queue.append(((nx, ny), steps + 1, True))
                    elif grid[nx][ny] == 0:
                        queue.append(((nx, ny), steps + 1, broke))

        return float('inf')

    return min(bfs_with_break((0, 0)), bfs_with_break((rows-1, cols-1)))
