def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    for instruction in program:
        parts = instruction.split()
        if parts[0] == 'PUSH':
            stack.append(int(parts[1]))
        elif parts[0] == 'POP':
            if stack:
                stack.pop()
        elif parts[0] == 'ADD':
            if len(stack) >= 2:
                stack.append(stack.pop() + stack.pop())
        elif parts[0] == 'SUB':
            if len(stack) >= 2:
                stack.append(-stack.pop() + stack.pop())
        elif parts[0] == 'MUL':
            if len(stack) >= 2:
                stack.append(stack.pop() * stack.pop())
        elif parts[0] == 'DIV':
            if len(stack) >= 2:
                divisor = stack.pop()
                if divisor != 0:
                    stack.append(int(stack.pop() / divisor))
    return stack
