def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    for instruction in program:
        parts = instruction.split()
        if parts[0] == 'PUSH':
            stack.append(int(parts[1]))
        elif parts[0] == 'POP':
            if stack:
                stack.pop()
        elif parts[0] == 'ADD':
            if len(stack) >= 2:
                stack.append(stack.pop() + stack.pop())
        elif parts[0] == 'SUB':
            if len(stack) >= 2:
                stack.append(-stack.pop() + stack.pop())
        elif parts[0] == 'MUL':
            if len(stack) >= 2:
                stack.append(stack.pop() * stack.pop())
        elif parts[0] == 'DIV':
            if len(stack) >= 2:
                divisor = stack.pop()
                if divisor != 0:
                    stack.append(int(stack.pop() / divisor))
    return stack

def min_max_normalize(nums: list[float]) -> list[float]:
    if not nums:
        return []

    min_val = min(nums)
    max_val = max(nums)

    range_val = max_val - min_val

    if range_val == 0:
        return [0] * len(nums)  # Avoid division by zero if all elements are the same

    normalized_nums = [(num - min_val) / range_val for num in nums]
    return normalized_nums

