def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows or not aligns:
        return ""

    num_cols = len(rows[0])
    col_widths = [max(len(row[i]) for row in rows) for i in range(num_cols)]

    formatted_rows = []
    for row in rows:
        formatted_row = []
        for cell, align, width in zip(row, aligns, col_widths):
            if align == 'l':
                formatted_cell = f"{cell:<{width}}"
            elif align == 'r':
                formatted_cell = f"{cell:>{width}}"
            else:
                formatted_cell = f"{cell:^{width}}"
            formatted_row.append(formatted_cell)
        formatted_rows.append(" | ".join(formatted_row))

    header_separator = " | ".join(f"{'-' * width}" for width in col_widths)
    result = f"{header_separator}\n{' | '.join(rows[0])}\n{header_separator}\n"
    result += "\n".join(formatted_rows)

    return result
