def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    for instruction in program:
        parts = instruction.split()
        if len(parts) == 2 and parts[0].isdigit():
            stack.append(int(parts[1]))
        elif len(parts) == 3:
            op, a, b = parts
            a, b = int(a), int(b)
            if op == 'ADD':
                stack.append(a + b)
            elif op == 'SUB':
                stack.append(a - b)
            elif op == 'MUL':
                stack.append(a * b)
            elif op == 'DIV':
                if b != 0:
                    stack.append(a // b)
                else:
                    return None
    return stack
