def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    for instruction in program:
        parts = instruction.split()
        if len(parts) != 2:
            return None
        command, value = parts
        try:
            value = int(value)
        except ValueError:
            return None
        if command == 'PUSH':
            stack.append(value)
        elif command == 'POP':
            if not stack:
                return None
            stack.pop()
        else:
            return None
    return stack
