def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    for instruction in program:
        parts = instruction.split()
        if len(parts) == 0:
            continue
        command = parts[0]
        if command == 'PUSH':
            value = int(parts[1])
            stack.append(value)
        elif command == 'POP':
            if not stack:
                return None
            stack.pop()
        elif command == 'ADD':
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif command == 'SUB':
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif command == 'MUL':
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif command == 'DIV':
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            if b == 0:
                return None
            stack.append(int(a / b))
        else:
            return None
    return stack
