def serve_static(web_root: str, request_path: str) -> tuple[int, bytes]:
    file_path = os.path.join(web_root, request_path.lstrip('/'))

    if not os.path.exists(file_path):
        return 404, b'File not found'

    try:
        with open(file_path, 'rb') as file:
            content = file.read()
        return 200, content
    except Exception as e:
        return 500, f'Internal Server Error: {str(e)}'.encode('utf-8')
