from collections import OrderedDict

def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    cache = OrderedDict()
    hit_times = []
    miss_times = []

    for op in operations:
        if op[0] == 'GET':
            key = op[1]
            if key in cache:
                cache.move_to_end(key)
                hit_times.append(1)
            else:
                miss_times.append(1)
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = None
        elif op[0] == 'SET':
            key, value = op[1], op[2]
            if key in cache:
                cache.move_to_end(key)
            cache[key] = value
            if len(cache) > capacity:
                cache.popitem(last=False)

    return hit_times, miss_times
