def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    cache = OrderedDict()
    hit_times = []
    miss_times = []

    for operation in operations:
        if operation[0] == 'GET':
            key = operation[1]
            if key in cache:
                hit_times.append(key)
                cache.move_to_end(key)  # Move the accessed item to the end
            else:
                miss_times.append(key)
                if len(cache) >= capacity:
                    lru_key = next(iter(cache))  # Get the first item (LRU)
                    del cache[lru_key]
                cache[key] = None  # Value doesn't matter, just using it as a placeholder

    return hit_times, miss_times
```

