from collections import defaultdict

def find_bridges(n: int, edges: list[tuple[int, int]]) -> list[tuple[int, int]]:
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    discovery_time = [-1] * n
    low_value = [-1] * n
    parent = [-1] * n
    time = 0
    bridges = []

    def dfs(node):
        nonlocal time
        visited[node] = True
        discovery_time[node] = low_value[node] = time
        time += 1

        for neighbor in graph[node]:
            if not visited[neighbor]:
                parent[neighbor] = node
                dfs(neighbor)
                low_value[node] = min(low_value[node], low_value[neighbor])
                if discovery_time[node] < low_value[neighbor]:
                    bridges.append((node, neighbor))
            elif neighbor != parent[node]:
                low_value[node] = min(low_value[node], discovery_time[neighbor])

    for i in range(n):
        if not visited[i]:
            dfs(i)

    return bridges

