def top_products(conn, limit: int | str, category: str | None = None) -> list[tuple]:
    cursor = conn.cursor()

    if isinstance(limit, str):
        limit = int(limit)

    query = "SELECT product_id, product_name, price FROM products ORDER BY sales DESC LIMIT ?"
