    if category:
        query += " WHERE category = ?"
        params += (category,)

    cursor.execute(query, params)
    return cursor.fetchall()

import sqlite3

def top_products(conn, limit: int | str, category: str | None = None) -> list[tuple]:
    query = "SELECT product_name, price FROM products"
    if category:
        query += f" WHERE category = '{category}'"
    query += f" ORDER BY price DESC LIMIT {limit}"

    cursor = conn.cursor()
    cursor.execute(query)
    return cursor.fetchall()

