    for home, away, home_goals, away_goals in results:
        if home_goals > away_goals:
            table[home][0] += 3  # Home team wins
            table[away][2] += 1  # Away team loses
        elif away_goals > home_goals:
            table[away][0] += 3  # Away team wins
            table[home][2] += 1  # Home team loses
        else:
            table[home][1] += 1  # Home team draws
            table[away][1] += 1  # Away team draws

        table[home][2] += away_goals
        table[away][2] += home_goals

    return sorted(table.items(), key=lambda x: (-x[1][0], -x[1][2], x[0]))

