def sparse_vector_dot(v1: dict[int, float], v2: dict[int, float]) -> float:
    # Initialize the dot product result
    dot_product = 0.0

    # Iterate over the first vector's items
    for idx, val in v1.items():
        # Add the product of the values from both vectors at the current index to the result
        if idx in v2:
            dot_product += val * v2[idx]

    # Round the result to three decimal places and return it
    return round(dot_product, 3)
