    rows = max(len(a), len(b))
    cols = max(len(row) for row in a + b)

    result = [[0] * cols for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            val_a = a[i][j] if i < len(a) and j < len(a[i]) else 0
            val_b = b[i][j] if i < len(b) and j < len(b[i]) else 0
            result[i][j] = val_a + val_b

    return result

