def longest_consecutive_streak(items: list[int]) -> int:
    if not items:
        return 0

    unique_items = set(items)
    longest_streak = 0

    for item in unique_items:
        if item - 1 not in unique_items:
            current_item = item
            current_streak = 1

            while current_item + 1 in unique_items:
                current_item += 1
                current_streak += 1

            longest_streak = max(longest_streak, current_streak)

    return longest_streak
