def longest_bitonic_length(nums: List[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0

    # Initialize arrays to store the length of the longest increasing subsequence ending at each index
    lis = [1] * n

    # Compute LIS values from left to right
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
