def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0

    def bit_length(n):
        return n.bit_length()

    def count_bits_in_range(start, end):
        if start == end:
            return bit_length(start)
        msb_start = bit_length(start - 1)
        msb_end = bit_length(end)
        if msb_start != msb_end:
            return (1 << msb_start) + count_bits_in_range(1 << msb_start, end)
        else:
            return end - start + 1

    return count_bits_in_range(lo, hi)
