def min_coins_bounded(coins: List[int], limits: List[int], target: int) -> int:
    if target == 0:
        return 0

    n = len(coins)
    dp = [float('inf')] * (target + 1)
    dp[0] = 0

    for i in range(n):
        for j in range(target, -1, -1):
            if j >= coins[i]:
