import yaml

def parse_jobs(text: str) -> list[dict]:
    if not text:
        return []

    jobs = yaml.safe_load(text)
    parsed_jobs = []

    for job in jobs:
        name = job.get('name')
        interval = job.get('interval')
        enabled = job.get('enabled', True)

        if name is None or interval is None:
            continue

        parsed_job = {
            'name': name,
            'interval': interval,
            'enabled': enabled
        }
        parsed_jobs.append(parsed_job)

    return parsed_jobs

