import operator

def evaluate_expression(expression: str) -> float:
    ops = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv,
        '**': operator.pow,
    }

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '/' and right == 0:
            raise ZeroDivisionError("division by zero")
        values.append(ops[operator](left, right))

    def greater_precedence(op1, op2):
        return ops[op1].__precedence__ > ops[op2].__precedence__

    tokens = []
    i = 0
    while i < len(expression):
        if expression[i] == ' ':
            i += 1
            continue
        elif expression[i].isdigit() or expression[i] == '.':
            j = i
            while j < len(expression) and (expression[j].isdigit() or expression[j] == '.'):
                j += 1
            tokens.append(float(expression[i:j]))
            i = j
        elif expression[i] in ops:
            while (operators and operators[-1] != '(' and
                   greater_precedence(operators[-1], expression[i])):
                apply_operator(operators, values)
            operators.append(expression[i])
            i += 1
        elif expression[i] == '(':
            operators.append(expression[i])
            i += 1
        elif expression[i] == ')':
            while operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()  # Remove '('
            i += 1
        else:
            raise ValueError(f"Unknown character: {expression[i]}")

    while operators:
        apply_operator(operators, values)

    if len(values) != 1:
        raise ValueError("Invalid expression")

    return values[0]
