from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols

    start, end = None, None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    queue = deque([(start, False)])
    visited = set([start + (False,)])

    while queue:
        (r, c), broke_wall = queue.popleft()

        if (r, c) == end:
            return 1

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                new_state = (nr, nc), broke_wall
                if grid[nr][nc] == '.' and new_state not in visited:
                    visited.add(new_state)
                    queue.append((new_state))
                elif grid[nr][nc] == '#' and not broke_wall and new_state not in visited:
                    visited.add(new_state)
                    queue.append(((nr, nc), True))

    return -1
