def longest_bitonic_length(nums: List[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0

    # Initialize two arrays to store the lengths of increasing and decreasing subsequences
    lis = [1] * n
    lds = [1] * n

    # Compute the LIS values from left to right
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Compute the LDS values from right to left
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if nums[i] > nums[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # Find the maximum length of bitonic subsequence
    max_length = 0
    for i in range(n):
        max_length = max(max_length, lis[i] + lds[i] - 1)

    return max_length
