from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    queue = deque([(start, False)])
    visited = set()
    visited.add(start)

    while queue:
        (x, y), broke_wall = queue.popleft()

        if (x, y) == end:
            return 0

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                new_broke_wall = broke_wall or (grid[nx][ny] == '#')
                if (nx, ny, new_broke_wall) not in visited:
                    visited.add((nx, ny, new_broke_wall))
                    queue.append(((nx, ny), new_broke_wall))

    return -1
