from typing import List, Dict

def log_requests(log_path: str, requests: List[Dict[str, str]]) -> int:
    new_lines = []
    for req in requests:
        line = f"{req['timestamp']} {req['ip']} \"{req['path']}\" \"{req['user_agent']}\"\n"
        new_lines.append(line)

    with open(log_path, 'a', encoding='utf-8') as file:
        file.writelines(new_lines)

    return len(new_lines)

