import re

def decode_runs(encoded: str) -> str:
    decoded = []
    for match in re.finditer(r'(\\.)|([^\d\~])|\~(\d+)', encoded):
        if match.group(1):
            decoded.append(match.group(1)[1])
        elif match.group(2):
            decoded.append(match.group(2))
        else:
            count = int(match.group(3))
            decoded.extend([match.group(2)] * count)
    return ''.join(decoded)
