import re

def decode_runs(encoded: str) -> str:
    decoded = []
    tokens = re.findall(r'(\\.)|([^\d\~])|\~(\d+)', encoded)
    for token in tokens:
        char = token[0] if token[0] else token[1]
        count = int(token[2]) if token[2] else 1
        decoded.extend([char] * count)
    return ''.join(decoded)

