def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    blocked = {(r, c) for r, c in blocked if 0 <= r < n and 0 <= c < n}

    def is_safe(board, row, col):
        for i in range(col):
            if board[row][i] == 1:
                return False
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False
        return True

    def solve_n_queens(board, col):
        if col >= n:
            return 1
        count = 0
        for i in range(n):
            if (i, col) not in blocked and is_safe(board, i, col):
                board[i][col] = 1
                count += solve_n_queens(board, col + 1)
                board[i][col] = 0
        return count

    board = [[0 for _ in range(n)] for _ in range(n)]
    return solve_n_queens(board, 0)
