from collections import defaultdict, deque

def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    if n == 0:
        return []

    graph = defaultdict(list)
    indegree = [0] * n

    for a, b in pairs:
        if a == b:
            return []  # Cycle detected
        graph[a].append(b)
        indegree[b] += 1

    queue = deque([i for i in range(n) if indegree[i] == 0])
    result = []

    while queue:
        if len(queue) > 1:
            queue.sort()  # Sort to ensure lexicographical order
        node = queue.popleft()
        result.append(node)

        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    return result if len(result) == n else []
