        if remaining == 0:
            result.add(tuple(sorted(path)))
            return
        if remaining < 0:
            return
        for i in range(start, len(nums)):
            backtrack(i + 1, path + [nums[i]], remaining - nums[i])

    result = set()
    backtrack(0, [], k)
    return sorted(list(result))
