from typing import List, Tuple

def free_slots(busy: List[Tuple[int, int]], day_start: int, day_end: int, min_len: int) -> List[Tuple[int, int]]:
    if day_start >= day_end:
        return []

    busy = sorted([b for b in busy if b[0] < b[1]])
    merged_busy = [busy[0]]
    for start, end in busy[1:]:
        if start < merged_busy[-1][1]:
            merged_busy[-1] = (merged_busy[-1][0], max(merged_busy[-1][1], end))
        else:
            merged_busy.append((start, end))

    free = []
    current_start = day_start
    for start, end in merged_busy:
        if start > current_start:
            free.append((current_start, start))
        current_start = max(current_start, end)

    if current_start < day_end:
        free.append((current_start, day_end))

    return [(s, e) for s, e in free if e - s >= min_len]
