import ast

class FilterParser(ast.NodeTransformer):
    def __init__(self, record):
        self.record = record

    def visit_Name(self, node):
        if node.id in self.record:
            return ast.copy_location(
                ast.Num(self.record[node.id]), node)
        else:
            raise ValueError(f"Unknown variable: {node.id}")

    def visit_Compare(self, node):
        left = self.visit(node.left)
        right = self.visit(node.comparators[0])
        ops = {
            ast.Lt: lambda x, y: x < y,
            ast.LtE: lambda x, y: x <= y,
            ast.Gt: lambda x, y: x > y,
            ast.GtE: lambda x, y: x >= y,
            ast.Eq: lambda x, y: x == y,
            ast.NotEq: lambda x, y: x != y,
        }
        op = ops[type(node.ops[0])]
        return ast.copy_location(
            ast.Call(func=ast.Name(id='bool', ctx=ast.Load()),
                     args=[ast.BinOp(left=left, op=ast.BitXor(), right=right)],
                     keywords=[]), node)

def matches_filter(expression: str, record: dict) -> bool:
    try:
        parsed_expr = ast.parse(expression, mode='eval').body
        transformed_expr = FilterParser(record).visit(parsed_expr)
        return eval(compile(transformed_expr, filename="<ast>", mode="eval"))
    except (SyntaxError, NameError, TypeError, ValueError) as e:
        raise ValueError("Invalid expression") from e
