from collections import deque

def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None

    # Find the start and end positions
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS initialization
    queue = deque([start])
    visited = set([start])
    steps = 0

    while queue:
        for _ in range(len(queue)):
            x, y = queue.popleft()
            if (x, y) == end:
                return steps
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                while 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#':
                    nx += dx
                    ny += dy
                nx -= dx
                ny -= dy
                if (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny))
        steps += 1

    return -1
