    source = source.replace(' ', '').replace('\t', '').replace('\n', '')
    tokens = []
    i = 0
    while i < len(source):
        match = None
        if source[i:i+2] in ['==', '!=', '<=', '>=']:
            match = ('OP', source[i:i+2])
            i += 2
        elif source[i] in '+-*/<>,()':
            match = ('OP', source[i])
            i += 1
        elif source[i].isdigit():
            start = i
            while i < len(source) and source[i].isdigit():
                i += 1
            if i < len(source) and source[i] == '.':
                i += 1
                while i < len(source) and source[i].isdigit():
                    i += 1
            match = ('NUMBER', source[start:i])
        elif source[i].isalpha() or source[i] == '_':
            start = i
            while i < len(source) and (source[i].isalnum() or source[i] == '_'):
                i += 1
            match = ('NAME', source[start:i])
        else:
            raise ValueError(f"Invalid character at position {i}: {source[i]}")
        tokens.append(match)
    return tokens
