def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    queue = deque([(source, 1)])
    visited = {source}
    shortest_paths_count = 0

    while queue:
        current_node, current_path_length = queue.popleft()

        if current_node == target:
            shortest_paths_count += current_path_length

        for neighbor in graph[current_node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, current_path_length + 1))

    return shortest_paths_count
