import re

def parse_csv(text: str) -> list[list[str]]:
    if not text:
        return []

    def parse_field(field):
        if field.startswith('"'):
            field = field[1:]
            while True:
                match = re.search(r'(?<!")"(?=[^"]*$)', field)
                if not match:
                    break
                field = field[:match.start()] + field[match.end():]
            if field.endswith('"'):
                field = field[:-1]
            return field.replace('""', '"')
        return field

    lines = text.split('\n')
    result = []
    for line in lines:
        if line.strip():
            fields = [parse_field(f) for f in re.split(r'(?:,(?=(?:[^"]*"[^"]*")*[^"]*$))', line)]
            result.append(fields)
        else:
            result.append([''])
    return result
