def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    blocked = {(r, c) for r, c in blocked if 0 <= r < n and 0 <= c < n}

    def is_safe(row: int, col: int) -> bool:
        for i in range(n):
            if (i, col) in blocked or (row, i) in blocked:
                continue
            if abs(i - row) == abs(col - i):
                if (i, col) in blocked or (row, i) in blocked:
                    continue
                return False
        return True

    def backtrack(row: int) -> int:
        if row == n:
            return 1
        count = 0
        for col in range(n):
            if (row, col) not in blocked and is_safe(row, col):
                count += backtrack(row + 1)
        return count

    return backtrack(0)
