from typing import List, Tuple

def find_bridges(n: int, edges: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    from collections import defaultdict

    def dfs(node: int, parent: int) -> None:
        nonlocal time
        discovery[node] = lowlink[node] = time
        time += 1

        for neighbor in adj_list[node]:
            if neighbor == parent:
                continue
            if discovery[neighbor] == -1:
                dfs(neighbor, node)
                lowlink[node] = min(lowlink[node], lowlink[neighbor])
                if lowlink[neighbor] > discovery[node]:
                    bridges.add((min(node, neighbor), max(node, neighbor)))
            else:
                lowlink[node] = min(lowlink[node], discovery[neighbor])

    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    discovery = [-1] * n
    lowlink = [-1] * n
    time = 0
    bridges = set()

    for i in range(n):
        if discovery[i] == -1:
            dfs(i, -1)

    return sorted(bridges)
