def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix:
        return []

    n = len(matrix)
    result = [row[:] for row in matrix]
    layers = (n + 1) // 2

    for layer in range(layers):
        start = layer
        end = n - layer - 1

        if end - start <= abs(k):
            continue

        k = k % (end - start)

        for i in range(start, end):
            temp = result[start][i]
            for j in range(start, end):
                result[j][i], temp = temp, result[j][i]
            for j in range(end, start, -1):
                result[j][end], temp = temp, result[j][end]
            for j in range(end, start, -1):
                result[start][j], temp = temp, result[start][j]
            for j in range(start, end):
                result[i][start], temp = temp, result[i][start]

    return result
