import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    source = source.replace('\n', ' ').replace('\t', ' ')
    tokens = []
    i = 0
    while i < len(source):
        if source[i].isdigit():
            match = re.match(r'\d+(\.\d+)?', source[i:])
            if match:
                tokens.append(('NUMBER', match.group(0)))
                i += match.end()
            else:
                raise ValueError("Invalid number")
        elif source[i].isalpha() or source[i] == '_':
            match = re.match(r'[a-zA-Z_]\w*', source[i:])
            if match:
                tokens.append(('NAME', match.group(0)))
                i += match.end()
            else:
                raise ValueError("Invalid name")
        elif source[i:i+2] in ('==', '!=', '<=', '>='):
            tokens.append(('OP', source[i:i+2]))
            i += 2
        elif source[i] in '+-*/(),=<>()':
            tokens.append(('OP', source[i]))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {source[i]}")
    return tokens
