        parsed_expr = ast.parse(expression, mode='eval').body
        evaluator = FilterExpressionEvaluator(record)
        compiled_expr = compile(evaluator.visit(parsed_expr), filename="<ast>", mode="eval")
        return eval(compiled_expr)
    except (SyntaxError, NameError, TypeError) as e:
        raise ValueError("Invalid expression") from e

