def league_table(results: list[tuple[str, str, int, int]]) -> list[tuple[str, int, int, int]]:
    if not results:
        return []

    standings = defaultdict(lambda: {'points': 0, 'goals_for': 0, 'goals_against': 0})

    for home, away, home_goals, away_goals in results:
        standings[home]['goals_for'] += home_goals
        standings[home]['goals_against'] += away_goals
        standings[away]['goals_for'] += away_goals
        standings[away]['goals_against'] += home_goals

        if home_goals > away_goals:
            standings[home]['points'] += 3
        elif home_goals == away_goals:
            standings[home]['points'] += 1
            standings[away]['points'] += 1

    sorted_standings = sorted(
        [(team, data['points'], data['goals_for'] - data['goals_against'], data['goals_for'])
         for team, data in standings.items()],
        key=lambda x: (-x[1], -x[2], -x[3], x[0])
    )

    return sorted_standings
