def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == '-' or any(char not in '0123456789abcdefghijklmnopqrstuvwxyz'[:from_base] for char in number):
        raise ValueError("Invalid input")

    if number.startswith('-'):
        is_negative = True
        number = number[1:]
    else:
        is_negative = False

    decimal_number = int(number, from_base)

    if decimal_number == 0:
        return "0"

    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    result = []

    while decimal_number > 0:
        remainder = decimal_number % to_base
        result.append(digits[remainder])
        decimal_number //= to_base

    if is_negative:
        result.append('-')

    return ''.join(reversed(result))
