import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    pattern = re.compile(r'\s*(?:(\d+\.\d*|\.\d+)|([a-zA-Z_]\w*)|([+\-*/<>=(),])|\.)')
    i = 0
    while i < len(source):
        match = pattern.match(source, i)
        if not match:
            raise ValueError("Unexpected character encountered")
        kind, text = match.groups()
        if kind:
            if kind == '.':
                raise ValueError("Unexpected '.' without a preceding number")
            tokens.append((kind, text))
        i = match.end()
    return tokens

