def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    num_cols = len(rows[0])
    col_widths = [max(len(cell) for cell in col) for col in zip(*rows)]

    def pad_cell(cell: str, width: int, align: str) -> str:
        if align == "l":
            return cell.ljust(width)
        elif align == "r":
            return cell.rjust(width)
        elif align == "c":
            padding = width - len(cell)
            left_pad = padding // 2
            right_pad = padding - left_pad
            return cell.center(width, ' ')
        else:
            raise ValueError("Invalid alignment")

    formatted_rows = []
    for row in rows:
        formatted_cells = [
            pad_cell(cell, width, aligns[i]) for i, (cell, width) in enumerate(zip(row, col_widths))
        ]
        formatted_rows.append(" | ".join(formatted_cells))

    return "\n".join(formatted_rows)
