def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    max_executions = 1000

    while 0 <= ip < len(program):
        if max_executions == 0:
            return None
        max_executions -= 1

        parts = program[ip].split()
        opcode = parts[0]

        if opcode == 'PUSH':
            stack.append(int(parts[1]))
        elif opcode == 'POP':
            if not stack:
                return None
            stack.pop()
        elif opcode == 'DUP':
            if not stack:
                return None
            stack.append(stack[-1])
        elif opcode == 'SWAP':
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif opcode == 'ADD':
            if len(stack) < 2:
                return None
            stack.append(stack.pop() + stack.pop())
        elif opcode == 'SUB':
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif opcode == 'MUL':
            if len(stack) < 2:
                return None
            stack.append(stack.pop() * stack.pop())
        elif opcode == 'JMP':
            ip = int(parts[1]) - 1
        elif opcode == 'JZ':
            if not stack:
                return None
            if stack.pop() == 0:
                ip = int(parts[1]) - 1

        ip += 1

    return stack
