def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0
    max_instructions = 1000

    while ip < len(program) and len(stack) <= 1000:
        instruction = program[ip].split()
        max_instructions -= 1

        if instruction[0] == 'PUSH':
            stack.append(int(instruction[1]))
        elif instruction[0] == 'POP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif instruction[0] == 'DUP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif instruction[0] == 'SWAP':
            if len(stack) < 2:
                raise ValueError("Not enough elements for SWAP")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction[0] == 'ADD':
            if len(stack) < 2:
                raise ValueError("Not enough elements for ADD")
            stack.append(stack.pop() + stack.pop())
        elif instruction[0] == 'SUB':
            if len(stack) < 2:
                raise ValueError("Not enough elements for SUB")
            stack.append(-stack.pop() + stack.pop())
        elif instruction[0] == 'MUL':
            if len(stack) < 2:
                raise ValueError("Not enough elements for MUL")
            stack.append(stack.pop() * stack.pop())
        elif instruction[0] == 'JMP':
            try:
                ip = int(instruction[1])
            except ValueError:
                raise ValueError("Invalid JMP target")
        elif instruction[0] == 'JZ':
            if not stack:
                raise ValueError("Stack underflow")
            if stack[-1] == 0:
                try:
                    ip = int(instruction[1])
                except ValueError:
                    raise ValueError("Invalid JZ target")
            else:
                ip += 1
        elif instruction[0] == 'HALT':
            break
        else:
            raise ValueError(f"Unknown instruction: {instruction[0]}")

        if max_instructions == 0:
            raise RuntimeError("Maximum number of instructions exceeded")

        ip += 1

    return stack[::-1]
