from collections import defaultdict

def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = defaultdict(int)
    waiting = defaultdict(list)

    for kind, item, quantity in events:
        if kind == 'receive':
            while waiting[item] and waiting[item][0][1] <= quantity:
                _, order_quantity = waiting[item].pop(0)
                quantity -= order_quantity
            if quantity > 0:
                waiting[item].append((item, quantity))
            stock[item] += quantity
        elif kind == 'order':
            if stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting[item].append((item, quantity))

    # Remove items with zero stock from the stock dictionary
    stock = {item: qty for item, qty in stock.items() if qty > 0}

    # Flatten the waiting dictionary into a list of tuples
    waiting_list = [order for orders in waiting.values() for order in orders]

    return dict(stock), waiting_list
