def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0
    max_instructions = 1000

    while ip < len(program):
        if max_instructions == 0:
            raise RuntimeError("Maximum number of instructions exceeded")

        instruction = program[ip].split()
        op = instruction[0]

        if op == 'PUSH':
            stack.append(int(instruction[1]))
        elif op == 'POP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif op == 'DUP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif op == 'SWAP':
            if len(stack) < 2:
                raise ValueError("Not enough elements for swap")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == 'ADD':
            if len(stack) < 2:
                raise ValueError("Not enough elements for addition")
            stack.append(stack.pop() + stack.pop())
        elif op == 'SUB':
            if len(stack) < 2:
                raise ValueError("Not enough elements for subtraction")
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif op == 'MUL':
            if len(stack) < 2:
                raise ValueError("Not enough elements for multiplication")
            stack.append(stack.pop() * stack.pop())
        elif op == 'JMP':
            try:
                target = int(instruction[1])
                if target < 0 or target >= len(program):
                    raise ValueError("Invalid jump target")
                ip = target
                continue
            except ValueError:
                raise ValueError("Invalid jump target")
        elif op == 'JZ':
            if len(stack) < 1:
                raise ValueError("Not enough elements for conditional jump")
            if stack[-1] == 0:
                try:
                    target = int(instruction[1])
                    if target < 0 or target >= len(program):
                        raise ValueError("Invalid jump target")
                    ip = target
                    continue
                except ValueError:
                    raise ValueError("Invalid jump target")
        elif op == 'HALT':
            break
        else:
            raise ValueError(f"Unknown opcode: {op}")

        ip += 1
        max_instructions -= 1

    return stack[::-1]
